patch:
diff --git a/repro/no-loss-of-precision-trailing-zeros.js b/repro/no-loss-of-precision-trailing-zeros.js
new file mode 100644
index 0000000..97b980b
--- /dev/null
+++ b/repro/no-loss-of-precision-trailing-zeros.js
@@ -0,0 +1,38 @@
+"use strict";
+
+/*
+ * Check: `no-loss-of-precision` must not flag number literals whose value is
+ * exactly representable, such as `9.000e+3` (== 9000).
+ * Exits 1 while any of these literals is reported, 0 once none is.
+ */
+
+const { Linter } = require("../lib/api");
+
+const linter = new Linter();
+const literals = [
+	"9.000e+3", // from the report
+	"9.000e3", // from the maintainer's comment
+	"9.0000e4", // from the maintainer's comment
+	"9.000e4", // control: not reported
+	"9.0000e5", // control: not reported
+];
+
+let failed = false;
+
+for (const literal of literals) {
+	const messages = linter.verify(`const test = ${literal}`, [
+		{ rules: { "no-loss-of-precision": "error" } },
+	]);
+
+	if (messages.length) {
+		failed = true;
+		console.log(`FLAGGED   ${literal}: ${messages[0].message}`);
+	} else {
+		console.log(`not flagged ${literal}`);
+	}
+}
+
+if (failed) {
+	console.error("no-loss-of-precision reported an exactly representable literal");
+	process.exit(1);
+}
